INSERT INTO ask_answers (key, handler, enabled, sort_order, phrases, question, answer, links) VALUES
  ($k$lead_time$k$, NULL, FALSE, 10, $q$["How long does it take to make a work?", "How long until my figurine is ready?", "What is the production time?", "Сколько времени занимает изготовление работы?", "Через какое время будет готова моя фигурка?", "Какой срок исполнения заказа?", "Как быстро вы делаете работу?", "Скільки часу триває виготовлення?", "Wie lange dauert die Anfertigung einer Figur?", "¿Cuánto tarda en estar lista una figura?"]$q$::jsonb, $q${"en": "How long does it take to make a work?", "ru": "Сколько времени занимает изготовление работы?", "uk": "Скільки часу триває виготовлення?"}$q$::jsonb, $q${}$q$::jsonb, $q$[]$q$::jsonb),
  ($k$how_order$k$, NULL, TRUE, 20, $q$["How do I order a figurine?", "How can I acquire a work from the collection?", "What are the steps to get a piece?", "Как заказать или приобрести работу?", "Какие шаги нужно пройти, чтобы получить фигурку?", "Как оформить покупку работы?", "Хочу взять эту фигурку, что делать дальше?", "Як замовити роботу?", "Come posso ordinare un'opera?", "Wie kann ich eine Figur erwerben?"]$q$::jsonb, $q${"en": "How do I order a figurine?", "ru": "Как заказать или приобрести работу?", "uk": "Як замовити роботу?"}$q$::jsonb, $q${"en": "Choose a finished work and send a request, or commission a new one. You write to the master directly; nothing is charged and nothing is owed until you both agree. If the master takes the work, they write to you personally with the terms.", "ru": "Выберите готовую работу и отправьте запрос — или закажите новую. Вы пишете мастеру напрямую; пока вы не договоритесь, ничего не списывается и ни к чему не обязывает. Если мастер берётся за работу, он лично пишет вам с условиями.", "uk": "Оберіть готову роботу й надішліть запит — або замовте нову. Ви пишете майстру напряму; доки ви не домовитеся, нічого не списується і ні до чого не зобов’язує. Якщо майстер береться за роботу, він особисто пише вам з умовами."}$q$::jsonb, $q$[{"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}, {"href": "/commission", "label": {"en": "Commission a work", "ru": "Заказать работу", "uk": "Замовити роботу"}}, {"href": "/figurines", "label": {"en": "All works", "ru": "Все работы", "uk": "Усі роботи"}}]$q$::jsonb),
  ($k$price$k$, NULL, TRUE, 30, $q$["How much does a work cost?", "What are your prices?", "Is it expensive?", "Сколько стоит работа?", "Какая цена у фигурки?", "Во сколько обойдётся покупка?", "Где посмотреть стоимость работ?", "Скільки коштує робота?", "Was kostet eine Figur?", "¿Cuál es el precio de una obra?"]$q$::jsonb, $q${"en": "How much does a work cost?", "ru": "Сколько стоит работа?", "uk": "Скільки коштує робота?"}$q$::jsonb, $q${"en": "There are no prices on the site: the master names the terms personally, in a message. Nothing is charged until you both agree.", "ru": "Цен на сайте нет: условия мастер называет лично в переписке. Пока вы не договоритесь, ничего не списывается.", "uk": "Цін на сайті немає: умови майстер називає особисто в листуванні. Доки ви не домовитеся, нічого не списується."}$q$::jsonb, $q$[{"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}]$q$::jsonb),
  ($k$shipping$k$, NULL, TRUE, 40, $q$["Do you ship abroad?", "How are the works delivered to me?", "Which countries do you deliver to?", "Есть ли доставка и в какие страны?", "Как отправляют работы покупателю?", "Отправите ли вы в другой город или за границу?", "Как упаковывают и пересылают фигурки?", "Чи є доставка за кордон?", "¿Hacen envíos internacionales?", "Versenden Sie ins Ausland?"]$q$::jsonb, $q${"en": "Do you ship abroad?", "ru": "Есть ли доставка и в какие страны?", "uk": "Чи є доставка за кордон?"}$q$::jsonb, $q${"en": "Delivery is insured, tracked, and one-way — packed by hand and photographed before it travels. The balance is settled before the work leaves the workshop.", "ru": "Доставка застрахованная, с отслеживанием и в одну сторону — работа упакована вручную и сфотографирована перед отправкой. Остаток оплачивается до того, как она покинет мастерскую.", "uk": "Доставка застрахована, з відстеженням і в один бік — робота запакована вручну й сфотографована перед відправленням. Решта сплачується до того, як вона залишить майстерню."}$q$::jsonb, $q$[{"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}]$q$::jsonb),
  ($k$payment$k$, NULL, TRUE, 50, $q$["How can I pay?", "Which payment methods do you accept?", "Do you take cards or bank transfer?", "Как можно оплатить заказ?", "Какие способы оплаты принимаете?", "Можно ли оплатить переводом или картой?", "Нужна ли предоплата, как расплачиваться?", "Як можна оплатити?", "Wie kann ich bezahlen?", "¿Cómo se paga el pedido?"]$q$::jsonb, $q${"en": "How can I pay?", "ru": "Как можно оплатить заказ?", "uk": "Як можна оплатити?"}$q$::jsonb, $q${"en": "A non-refundable deposit secures the piece and covers materials and time. The balance is settled before the work leaves the workshop. The master names the terms personally.", "ru": "Невозвратный депозит закрепляет работу и покрывает материалы и время. Остаток оплачивается до того, как работа покинет мастерскую. Условия мастер называет лично.", "uk": "Безповоротний завдаток закріплює роботу, покриває матеріали й час. Решта сплачується до того, як робота залишить майстерню. Умови майстер називає особисто."}$q$::jsonb, $q$[{"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}]$q$::jsonb),
  ($k$commission$k$, NULL, TRUE, 60, $q$["Can I commission a custom figurine?", "Do you make figurines to order from my idea?", "Can you create a piece based on my character?", "Можно ли заказать фигурку на заказ по моей идее?", "Делаете ли вы работы по индивидуальному заказу?", "Сможете ли вы создать персонажа по моему описанию?", "Хочу уникальную фигурку, которой нет на сайте", "Чи можна замовити фігурку за моїм задумом?", "¿Se puede encargar una figura personalizada?", "Fertigen Sie nach Kundenwunsch?"]$q$::jsonb, $q${"en": "Can I commission a custom figurine?", "ru": "Можно ли заказать фигурку на заказ по моей идее?", "uk": "Чи можна замовити фігурку за моїм задумом?"}$q$::jsonb, $q${"en": "Yes. Send a request to commission a new work and write to the master directly: nothing is charged until you both agree. For a commission the figure takes shape by hand, one stage at a time, and you may follow its progress.", "ru": "Да. Отправьте запрос на новую работу и пишите мастеру напрямую: пока вы не договоритесь, ничего не списывается. Для заказа фигура рождается вручную, шаг за шагом, и вы можете следить за ходом работы.", "uk": "Так. Надішліть запит на нову роботу й пишіть майстру напряму: доки ви не домовитеся, нічого не списується. Для замовлення фігура народжується вручну, крок за кроком, і ви можете стежити за ходом роботи."}$q$::jsonb, $q$[{"href": "/commission", "label": {"en": "Commission a work", "ru": "Заказать работу", "uk": "Замовити роботу"}}, {"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}]$q$::jsonb),
  ($k$care$k$, NULL, FALSE, 70, $q$["How do I take care of a figurine?", "How should I store the figurine?", "Can I clean the work or is it fragile?", "Как ухаживать за фигуркой?", "Как правильно хранить работу дома?", "Можно ли мыть фигурку, чем чистить?", "Боится ли фигурка солнца или влажности?", "Як доглядати за фігуркою?", "Wie pflege und lagere ich die Figur?", "¿Cómo se limpia y conserva la figura?"]$q$::jsonb, $q${"en": "How do I take care of a figurine?", "ru": "Как ухаживать за фигуркой?", "uk": "Як доглядати за фігуркою?"}$q$::jsonb, $q${}$q$::jsonb, $q$[]$q$::jsonb),
  ($k$returns$k$, NULL, TRUE, 80, $q$["Can I return a work?", "What is your return policy?", "What happens if the work is damaged on arrival?", "Можно ли вернуть работу?", "Каковы условия возврата?", "Что делать, если фигурка пришла повреждённой?", "Могу ли я обменять или отказаться от покупки?", "Чи можна повернути роботу?", "Posso restituire un'opera?", "¿Aceptan devoluciones?"]$q$::jsonb, $q${"en": "Can I return a work?", "ru": "Можно ли вернуть работу?", "uk": "Чи можна повернути роботу?"}$q$::jsonb, $q${"en": "Each piece is fragile and one of a kind, so all sales are final and returns are not possible. Delivery is insured, and every work is photographed before it travels.", "ru": "Каждая работа хрупкая и единственная в своём роде, поэтому все продажи финальные и возврат невозможен. Доставка застрахована, а перед отправкой работа фотографируется.", "uk": "Кожна робота крихка й єдина у своєму роді, тому всі продажі фінальні й повернення неможливе. Доставка застрахована, а перед відправленням робота фотографується."}$q$::jsonb, $q$[{"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}]$q$::jsonb),
  ($k$order_status$k$, NULL, TRUE, 90, $q$["How can I check the status of my order?", "Where can I see how my order is going?", "Can I track my parcel?", "Как узнать, на каком этапе мой заказ?", "Где посмотреть статус заказа или посылки?", "Можно ли отследить отправление?", "Заказ сделан, как следить за его ходом?", "Як дізнатися статус замовлення?", "Wo sehe ich den Stand meiner Bestellung?", "¿Dónde veo el estado de mi pedido?"]$q$::jsonb, $q${"en": "How can I check the status of my order?", "ru": "Как узнать, на каком этапе мой заказ?", "uk": "Як дізнатися статус замовлення?"}$q$::jsonb, $q${"en": "Delivery is tracked. For a commission, you may follow its progress and speak with the master along the way. Your requests and the replies are kept in your profile.", "ru": "Доставка отслеживается. Если работа на заказ, вы можете следить за ходом и общаться с мастером по пути. Ваши запросы и ответы мастера лежат в профиле.", "uk": "Доставка відстежується. Якщо робота на замовлення, ви можете стежити за ходом і спілкуватися з майстром дорогою. Ваші запити й відповіді майстра лежать у профілі."}$q$::jsonb, $q$[{"href": "/profile/dealings", "label": {"en": "My requests", "ru": "Мои обращения", "uk": "Мої звернення"}}]$q$::jsonb),
  ($k$contact$k$, NULL, TRUE, 100, $q$["How can I contact the author?", "How do I write to the maker?", "Where can I send a message or email?", "Как связаться с автором?", "Как написать мастеру лично?", "Куда обратиться с вопросом или проблемой?", "Есть ли почта или мессенджер для связи?", "Як зв'язатися з автором?", "Come contattare l'autrice?", "¿Cómo escribo a la autora?"]$q$::jsonb, $q${"en": "How can I contact the author?", "ru": "Как связаться с автором?", "uk": "Як зв'язатися з автором?"}$q$::jsonb, $q${"en": "You can write to the author with the “Write” button in the header or the form on the home page. The author reads every message and answers personally, usually within a day.", "ru": "Написать автору можно кнопкой «Написать» в шапке или формой на главной странице. Автор читает каждое письмо и отвечает лично, обычно в течение дня.", "uk": "Написати авторові можна кнопкою «Написати» в шапці або формою на головній сторінці. Автор читає кожен лист і відповідає особисто, зазвичай протягом дня."}$q$::jsonb, $q$[{"href": "/author", "label": {"en": "About the author", "ru": "Об авторе", "uk": "Про автора"}}, {"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}]$q$::jsonb),
  ($k$author$k$, NULL, TRUE, 110, $q$["Who makes these figurines?", "Who is the author of the works?", "Tell me about the maker", "Кто автор и кто делает фигурки?", "Расскажите о мастере, который всё это создаёт", "Кто стоит за этим сайтом и работами?", "Работает один человек или команда?", "Хто робить ці фігурки?", "¿Quién es la autora?", "Wer steckt hinter den Figuren?"]$q$::jsonb, $q${"en": "Who makes these figurines?", "ru": "Кто автор и кто делает фигурки?", "uk": "Хто робить ці фігурки?"}$q$::jsonb, $q${"en": "Every figurine is made by one author, who sculpts, paints and dresses each by hand, so no two are alike.", "ru": "Все фигурки делает один автор: каждую он лепит, расписывает и одевает вручную, поэтому двух одинаковых нет.", "uk": "Усі фігурки робить один автор: кожну він ліпить, розписує й одягає вручну, тому двох однакових немає."}$q$::jsonb, $q$[{"href": "/author", "label": {"en": "About the author", "ru": "Об авторе", "uk": "Про автора"}}, {"href": "/workshop", "label": {"en": "The workshop", "ru": "Мастерская", "uk": "Майстерня"}}]$q$::jsonb),
  ($k$materials$k$, NULL, TRUE, 120, $q$["What are the figurines made of?", "Which materials and techniques are used?", "How are the works made?", "Из чего сделаны фигурки?", "Какие материалы и техники использует мастер?", "Как создаются работы, из какого материала?", "Это глина, полимер или что-то другое?", "З чого зроблені фігурки?", "Woraus bestehen die Figuren?", "¿De qué material están hechas las figuras?"]$q$::jsonb, $q${"en": "What are the figurines made of?", "ru": "Из чего сделаны фигурки?", "uk": "З чого зроблені фігурки?"}$q$::jsonb, $q${"en": "The figurines are sculpted, painted and dressed by hand, and each exists in a single copy. The material and technique of each work are written on its page.", "ru": "Фигурки лепят, расписывают и одевают вручную, и каждая существует в единственном экземпляре. Материал и техника каждой работы указаны на её странице.", "uk": "Фігурки ліплять, розписують і одягають вручну, і кожна існує в єдиному екземплярі. Матеріал і техніка кожної роботи вказані на її сторінці."}$q$::jsonb, $q$[{"href": "/workshop", "label": {"en": "The workshop", "ru": "Мастерская", "uk": "Майстерня"}}, {"href": "/figurines", "label": {"en": "All works", "ru": "Все работы", "uk": "Усі роботи"}}]$q$::jsonb),
  ($k$size$k$, NULL, TRUE, 130, $q$["How big are the figurines?", "What are the dimensions of a work?", "What height is a typical piece?", "Какого размера фигурки?", "Какая высота у работ?", "Насколько большие фигурки, какие габариты?", "Сравнить размер с ладонью или книгой можно?", "Якого розміру фігурки?", "Quanto sono alte le statuine?", "¿Qué tamaño tienen las figuras?"]$q$::jsonb, $q${"en": "How big are the figurines?", "ru": "Какого размера фигурки?", "uk": "Якого розміру фігурки?"}$q$::jsonb, $q${"en": "The exact size is written on the page of each work.", "ru": "Точный размер указан на странице каждой работы.", "uk": "Точний розмір указано на сторінці кожної роботи."}$q$::jsonb, $q$[{"href": "/figurines", "label": {"en": "All works", "ru": "Все работы", "uk": "Усі роботи"}}]$q$::jsonb),
  ($k$unique$k$, NULL, TRUE, 140, $q$["Is each work unique?", "Are there copies or editions of a piece?", "Can the same figurine be made again?", "Каждая работа единственная?", "Бывают ли копии или повторы одной работы?", "Можно ли сделать такую же фигурку второй раз?", "Это штучная работа или серия?", "Кожна робота унікальна?", "¿Cada obra es única?", "Gibt es jede Figur nur einmal?"]$q$::jsonb, $q${"en": "Is each work unique?", "ru": "Каждая работа единственная?", "uk": "Кожна робота унікальна?"}$q$::jsonb, $q${"en": "Each work is one of a kind and exists in a single copy.", "ru": "Каждая работа единственная в своём роде и существует в одном экземпляре.", "uk": "Кожна робота єдина у своєму роді й існує в одному екземплярі."}$q$::jsonb, $q$[{"href": "/figurines", "label": {"en": "All works", "ru": "Все работы", "uk": "Усі роботи"}}]$q$::jsonb),
  ($k$is_shop$k$, NULL, TRUE, 150, $q$["Is this an online shop?", "Are you a store or a showcase?", "Can I just browse without buying?", "Это интернет-магазин?", "Здесь можно покупать или это витрина?", "Вы продаёте или только показываете работы?", "Это каталог, музей или магазин?", "Це магазин?", "Ist das ein Online-Shop?", "¿Esto es una tienda?"]$q$::jsonb, $q${"en": "Is this an online shop?", "ru": "Это интернет-магазин?", "uk": "Це магазин?"}$q$::jsonb, $q${"en": "This is a showcase of original gothic miniatures, not a shop. There is no cart and no checkout: to acquire a work, you write to the master.", "ru": "Это витрина авторских готических миниатюр, а не магазин. Ни корзины, ни оформления: чтобы получить работу, вы пишете мастеру.", "uk": "Це вітрина авторських готичних мініатюр, а не магазин. Ні кошика, ні оформлення: щоб отримати роботу, ви пишете майстру."}$q$::jsonb, $q$[{"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}, {"href": "/figurines", "label": {"en": "All works", "ru": "Все работы", "uk": "Усі роботи"}}]$q$::jsonb),
  ($k$discounts$k$, NULL, FALSE, 160, $q$["Are there discounts or promotions?", "Do you have sales or promo codes?", "Is there a loyalty offer?", "Бывают ли скидки и акции?", "Есть ли промокоды или распродажи?", "Можно ли купить дешевле?", "Делаете ли скидку постоянным покупателям?", "Чи бувають знижки?", "¿Hay descuentos u ofertas?", "Gibt es Rabatte oder Aktionen?"]$q$::jsonb, $q${"en": "Are there discounts or promotions?", "ru": "Бывают ли скидки и акции?", "uk": "Чи бувають знижки?"}$q$::jsonb, $q${}$q$::jsonb, $q$[]$q$::jsonb),
  ($k$reserve$k$, NULL, TRUE, 170, $q$["Can I reserve a work?", "How do I put a figurine on hold for myself?", "Can you keep a work for me for a while?", "Можно ли забронировать работу?", "Как отложить фигурку за собой?", "Могу ли я зарезервировать работу на время?", "Придержите ли вы работу, пока я решаюсь?", "Чи можна забронювати роботу?", "Posso prenotare un'opera?", "¿Puedo reservar una obra?"]$q$::jsonb, $q${"en": "Can I reserve a work?", "ru": "Можно ли забронировать работу?", "uk": "Чи можна забронювати роботу?"}$q$::jsonb, $q${"en": "If the master takes the work, they write to you personally with the terms. A non-refundable deposit secures the piece.", "ru": "Если мастер берётся за работу, он лично пишет вам с условиями. Невозвратный депозит закрепляет работу.", "uk": "Якщо майстер береться за роботу, він особисто пише вам з умовами. Безповоротний завдаток закріплює роботу."}$q$::jsonb, $q$[{"href": "/acquire", "label": {"en": "How to acquire a work", "ru": "Как приобрести работу", "uk": "Як придбати роботу"}}]$q$::jsonb),
  ($k$gift$k$, NULL, FALSE, 180, $q$["Can I buy a figurine as a gift?", "I am looking for a gift for a friend", "Can you recommend something for a present?", "Хочу выбрать работу в подарок", "Ищу подарок для близкого человека", "Что подойдёт в качестве подарка?", "Можно ли сделать подарочную упаковку?", "Хочу обрати роботу в подарунок", "Ich suche ein Geschenk", "Busco un regalo"]$q$::jsonb, $q${"en": "Can I buy a figurine as a gift?", "ru": "Хочу выбрать работу в подарок", "uk": "Хочу обрати роботу в подарунок"}$q$::jsonb, $q${}$q$::jsonb, $q$[]$q$::jsonb),
  ($k$play_rules$k$, NULL, TRUE, 190, $q$["How do I play the card game?", "What are the rules of the game?", "How does a battle work?", "Как играть, какие правила у игры?", "Объясните, как устроен бой", "Как работает карточная игра?", "Что делает ход, мана, дальность?", "Як грати, які правила?", "Come si gioca?", "¿Cómo se juega a las cartas?"]$q$::jsonb, $q${"en": "How do I play the card game?", "ru": "Как играть, какие правила у игры?", "uk": "Як грати, які правила?"}$q$::jsonb, $q${"en": "A study is a game against the computer on a small field. You place your cards and take turns; whoever still has cards when the opponent has none wins.\n\nEach study may have its own rules: they are written on the battle sheet before it starts. The first battles can be played without signing in.", "ru": "Этюд — партия против компьютера на небольшом поле. Вы расставляете карты и ходите по очереди; выигрывает тот, у кого остались карты, когда у противника их не осталось.\n\nУ каждого этюда могут быть свои правила: они написаны на листе боя перед началом. Первые бои можно играть без входа.", "uk": "Етюд — партія проти комп’ютера на невеликому полі. Ви розставляєте карти й ходите по черзі; виграє той, у кого залишилися карти, коли в противника їх не залишилося.\n\nУ кожного етюду можуть бути свої правила: вони написані на аркуші бою перед початком. Перші бої можна грати без входу."}$q$::jsonb, $q$[{"href": "/battles/etude", "label": {"en": "Studies", "ru": "Этюды", "uk": "Етюди"}}, {"href": "/battles", "label": {"en": "Card shelf", "ru": "Полка карт", "uk": "Полиця карт"}}]$q$::jsonb),
  ($k$play_first$k$, NULL, TRUE, 200, $q$["How do I start my first battle?", "I am new, how do I begin playing?", "Where do I start the game?", "Как начать первый бой?", "Я новичок, с какого этюда начать играть?", "Как запустить первую партию?", "Где открыть игру и какую встречу выбрать?", "Як почати перший бій?", "Wie starte ich den ersten Kampf?", "¿Cómo empiezo mi primera partida?"]$q$::jsonb, $q${"en": "How do I start my first battle?", "ru": "Как начать первый бой?", "uk": "Як почати перший бій?"}$q$::jsonb, $q${"en": "Open the studies and pick the first battle. The first battles can be played without signing in, and before each one the battle sheet tells its rules.", "ru": "Откройте этюды и выберите первый бой. Первые бои можно играть без входа, а перед каждым на листе боя написаны его правила.", "uk": "Відкрийте етюди й оберіть перший бій. Перші бої можна грати без входу, а перед кожним на аркуші бою написані його правила."}$q$::jsonb, $q$[{"href": "/battles/etude", "label": {"en": "Studies", "ru": "Этюды", "uk": "Етюди"}}]$q$::jsonb),
